package za.ac.cput.domain; import jakarta.persistence.*; import java.time.LocalDate;
@Entity public class Payment{@Id private String paymentId;private String bookingId;private double amount;private LocalDate paymentDate;private String paymentMethod;private String paymentStatus; protected Payment(){} private Payment(Builder b){paymentId=b.paymentId;bookingId=b.bookingId;amount=b.amount;paymentDate=b.paymentDate;paymentMethod=b.paymentMethod;paymentStatus=b.paymentStatus;} public String getPaymentId(){return paymentId;} public String getBookingId(){return bookingId;} public double getAmount(){return amount;} public LocalDate getPaymentDate(){return paymentDate;} public String getPaymentMethod(){return paymentMethod;} public String getPaymentStatus(){return paymentStatus;} public void processPayment(){paymentStatus="PAID";} public static class Builder{private String paymentId,bookingId,paymentMethod,paymentStatus;private double amount;private LocalDate paymentDate; public Builder setPaymentId(String v){paymentId=v;return this;} public Builder setBookingId(String v){bookingId=v;return this;} public Builder setAmount(double v){amount=v;return this;} public Builder setPaymentDate(LocalDate v){paymentDate=v;return this;} public Builder setPaymentMethod(String v){paymentMethod=v;return this;} public Builder setPaymentStatus(String v){paymentStatus=v;return this;} public Builder copy(Payment p){paymentId=p.paymentId;bookingId=p.bookingId;amount=p.amount;paymentDate=p.paymentDate;paymentMethod=p.paymentMethod;paymentStatus=p.paymentStatus;return this;} public Payment build(){return new Payment(this);}}}